def build(root="."):
    desc = json.load(open(os.path.join(ROOT, "data", "descriptors_en_1224.json"), encoding="utf-8"))
    tr = json.load(open(os.path.join(ROOT, "data", "working_translations_1224.json"), encoding="utf-8"))
    members = {int(no) for no, d in desc.items() if d.get("scale") == SCALE}
    assert members == set(ORDER), f"全数性不一致: {members ^ set(ORDER)}"
    assert len(ORDER) == 18
    for name, m in (("CONDITION", CONDITION), ("DEPTH", DEPTH)):
        tagged = [n for v in m.values() for n in v]
        assert sorted(tagged) == sorted(ORDER), f"{name}が完全分割でない"
    assert list(DEPTH.keys()) == SEVEN_LAYERS, "DEPTHの語彙が七層でない"
    order_lv = ["Pre-A1", "A1", "A2", "A2+", "B1", "B1+", "B2", "B2+", "C1", "C2"]
    arc = ["絵と写真", "短く簡単な言葉", "身近で具体的な状況と日常語", "出来事の記述と明示された気持ち", "辞書と参考資料", "広い読者向けの記事と平明な文体", "標準語か馴染みのある方言", "条件なし"]
    assert list(CONDITION.keys()) == arc
    prev_min = -1
    for c in arc:
        lv = sorted(order_lv.index(desc[str(n)]["level"]) for n in CONDITION[c])
        assert lv[0] >= prev_min, f"条件の列が級順でない: {c}"
        prev_min = lv[0]
    levels = {desc[str(n)]["level"] for n in ORDER}
    assert "Pre-A1" not in levels and {"A1", "C2"} <= levels, "このスケールはA1からC2まで（Pre-A1なし）"
    assert not DEPTH["形"] and not DEPTH["命題"] and not DEPTH["立場"], "楽しみに読む段に知っている言葉・一つの項目・立場の段はない"
    assert set(DEPTH["含意"]) == {n for n in ORDER if desc[str(n)]["level"] in ("C1", "C2")} == {189, 190, 188}, "含意の段＝C1・C2の全段（味わう三段）"
    assert set(DEPTH["筋"]) == {205, 201, 198, 197} and set(DEPTH["要点"]) == {203, 199, 193}, "筋の四段は物語の線、要点の三段は記事と記述の線"
    assert len(DEPTH["全体"]) == 8, "全体の段は8（過半でない）"
    assert all("appreciat" in desc[str(n)]["en"] for n in DEPTH["含意"]), "含意の三段は味わう段"
    for no, (ex, scene, hw, l1, delta) in R.items():
        assert not hw.startswith("形 ──") and not hw.startswith("命題 ──"), f"分かることの頭に裸の層名 No.{no}"
        for f in (scene, hw, l1, delta):
            assert "が取れる" not in f and not re.search(r"(態度|気分|視点|関係|好悪|立場|含意)を取", f), f"退役語形「〜が取れる」「態度などを取る」 No.{no}"
            assert "やり取り" not in f, f"四欄に「やり取り」（平仮名へ、判断(cf)） No.{no}"
            assert not re.search(r"との境[^目]|の境は|つの境", f), f"名詞の「境」（「境目」へ、判断(cm)） No.{no}"
            assert not re.search(r"(て|を)くれ", f) or re.search(r"(相手|話し手|書き手|人|語り手)が[^。]*(て|を)くれ", f), f"人でないものが主語の「〜してくれる」（判断(cm)） No.{no}"
        for e in ex:
            assert "\nYou: " in e, f"例に分かったしるしがない No.{no}"
    rows = []
    for no in ORDER:
        d = desc[str(no)]
        ex, scene, hw, l1, delta = R[no]
        rows.append({
            "mode": MODE, "level": d["level"], "no": no,
            "en": d["en"], "jp": tr[str(no)],
            "exponents": ex, "scene": scene, "howwell": hw, "l1": l1, "delta": delta,
        })
    sheet = {
        "title": "楽しみに読む（Reading as a leisure activity）── 第3柱量産第八号・全数シート",
        "scope": "全数（18件。読む18 ── mode一様。A1からC2まで、Pre-A1なし）",
        "type": "第3柱（受容）。梯子＝条件の解除の一本（絵と写真→短く簡単な言葉→身近で具体的な状況と日常語→出来事の記述と明示された気持ち→辞書と参考資料→広い読者向けの記事と平明な文体→標準語か馴染みのある方言→条件なし）、深さ＝七層（『受容の課題』§2）は段の属性。糸は立てない。四欄（scene＝読むもの・howwell＝分かること・l1・delta）は書物の本文そのもの（判断(bs)）。",
        "essence": "楽しみに読む段は、但し書きの担い手が文章の作りにある ── 絵と写真、短さと簡単さと日常語、明示された記述、辞書と参考資料が段ごとに外れ、辞書と参考資料の線は四段をかけてB1からC1まで薄くなる。読むものは物語の線と記事と記述の線に分かれ、物語は筋を追う段で上がって小説で全体になり、上端の三段は「分かる」から「味わう」へ出る。分かったことは返事でなく、読み続けるという読み手の振る舞いで示される。",
        "axes": {"条件": CONDITION, "深さ": DEPTH},
        "rows": rows,
        "discussion": DISCUSSION,
    }
    return {ACT: sheet}


if __name__ == "__main__":
    out = build()
    path = os.path.join(HERE, "catalog_p3_leisure.json")
    with open(path, "w", encoding="utf-8") as f:
        json.dump(out, f, ensure_ascii=False, indent=1)
    sheet = out[ACT]
    from collections import Counter
    print(f"生成OK: {path}")
    print(f"行数: {len(sheet['rows'])} / DISCUSSION: {len(sheet['discussion'])}段落")
    print("レベル分布:", dict(Counter(r["level"] for r in sheet["rows"])))
    print("落とし穴欄:", sum(1 for r in sheet["rows"] if r["l1"]), "/ 空欄:", [r["no"] for r in sheet["rows"] if not r["l1"]])
